  <el-dialog v-model="reportOpen" :title="'投递与领取追踪 · '+(selected?.name||'')" width="min(1200px,96vw)"><div class="activity-stat-grid"><div v-for="(label,key) in {sent:'已发送',received:'已收到',opened:'已打开',closed:'已关闭',closedWithoutOpening:'未打开即关闭',claimed:'已领取'}" :key="key"><strong>{{stats[key]||0}}</strong><span>{{label}}</span></div></div><div class="recipient-filters"><el-select v-model="filter" @change="recipientPage=1;report()"><el-option v-for="(label,key) in {ALL:'全部',SENT:'发送但未收到',RECEIVED:'已收到',OPENED:'已打开',CLOSED:'已关闭',CLOSED_UNOPENED:'收到后未打开即关闭',CLAIMED:'已领取'}" :key="key" :value="key" :label="label"/></el-select><el-input v-model="userFilter" placeholder="用户ID" clearable style="width:180px" @change="recipientPage=1;report()"/><el-button v-permission="'announcement:detail'" :loading="reportBusy" @click="report()">刷新</el-button></div><AccountTypeFilter v-model="recipientModes" @change="recipientPage=1;report()" /><admin-table :row-key="(row: any) => `${row.accountMode || 'REAL'}:${row.id ?? row.userId}:${row.type || ''}`" table-key="ActivityManagement.2" :data="recipients" v-loading="reportBusy"><el-table-column prop="accountModeLabel" label="账户类型" width="110" /><el-table-column prop="userId" label="用户ID" width="105"/><el-table-column v-for="(label,key) in {sentAt:'发送时间',receivedAt:'收到时间',openedAt:'首次打开',closedAt:'最后关闭',claimedAt:'领取时间'}" :key="key" :label="label" min-width="155"><template #default="{row}">{{date(row[key])}}</template></el-table-column><el-table-column label="打开/关闭" width="100"><template #default="{row}">{{row.openCount}} / {{row.closeCount}}</template></el-table-column><el-table-column label="账户" width="80"><template #default="{row}"><el-button v-permission="'announcement:detail'" link type="primary" @click="showLedger(row.userId,row.accountMode)">流水</el-button></template></el-table-column></admin-table><el-pagination v-model:current-page="recipientPage" :page-size="50" :total="recipientTotal" layout="total,prev,pager,next" @current-change="report()"/></el-dialog>
  <el-dialog v-model="ledgerOpen" title="体验金账户与最近50笔流水" width="min(900px,95vw)"><p>用户 {{account.userId}} · 可用 {{Number(account.available)}} U · 占用 {{Number(account.frozen)}} U · 累计消耗 {{Number(account.consumed)}} U · 净收益 {{Number(account.profits)}} U</p><AccountTypeFilter v-model="ledgerModes" @change="showLedger(account.userId)" /><admin-table :row-key="(row: any) => `${row.accountMode || 'REAL'}:${row.id ?? row.userId}:${row.type || ''}`" table-key="ActivityManagement.3" :data="ledger"><el-table-column prop="accountModeLabel" label="账户类型" width="110" /><el-table-column prop="reason" label="业务原因" min-width="200"/><el-table-column prop="delta" label="本金变化"/><el-table-column prop="available" label="可用"/><el-table-column prop="frozen" label="冻结"/><el-table-column label="时间" width="180"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column></admin-table></el-dialog>
 </section>
